import {
  Mesh,
  PlaneGeometry,
  DoubleSide,
  Object3D,
} from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // -------------------------------------------------
  // Geometry (aspect based on atlas source rect)
  // -------------------------------------------------
  const defaultRect = { width: 1, height: 1 };
  const sourceRect = (config.atlasRegion && config.atlasRegion.sourceRect) || defaultRect;
  const aspect = sourceRect.width / sourceRect.height;
  const geometry = new PlaneGeometry(aspect, 1);

  // -------------------------------------------------
  // Texture loading (synchronous via cached loader)
  // -------------------------------------------------
  const imageUrl = (config.assets && config.assets.imageUrl) || null;
  const tex = imageUrl ? ctx.textureLoader(imageUrl) : null;

  // -------------------------------------------------
  // Material selection (MeshBasicNodeMaterial per spec)
  // -------------------------------------------------
  const material = new MeshBasicNodeMaterial({
    map: tex ? texture(tex) : null,
    side: DoubleSide,
    transparent: true,
  });

  // -------------------------------------------------
  // Mesh assembly
  // -------------------------------------------------
  const mesh = new Mesh(geometry, material);
  mesh.position.set(
    (config.scenePlacement?.position?.[0]) ?? 0,
    (config.scenePlacement?.position?.[1]) ?? 0,
    (config.scenePlacement?.position?.[2]) ?? 0,
  );
  mesh.rotation.set(
    (config.scenePlacement?.rotation?.[0]) ?? 0,
    (config.scenePlacement?.rotation?.[1]) ?? 0,
    (config.scenePlacement?.rotation?.[2]) ?? 0,
  );
  mesh.scale.set(
    (config.scenePlacement?.scale?.[0]) ?? 1,
    (config.scenePlacement?.scale?.[1]) ?? 1,
    (config.scenePlacement?.scale?.[2]) ?? 1,
  );

  // -------------------------------------------------
  // Apply cinematic primitives (none in this spec)
  // -------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(mesh, prim.params);
      }
    });
  }

  // -------------------------------------------------
  // User data – empty handlers and cleanup
  // -------------------------------------------------
  const timelines = []; // store any GSAP timelines if created later

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    // Kill any GSAP timelines that might have been stored
    timelines.forEach((t) => {
      if (t && typeof t.kill === 'function') t.kill();
    });
    // Dispose Three.js resources
    geometry.dispose();
    material.dispose();
    if (tex && tex.dispose) tex.dispose();
  };

  // Ensure returned object is an Object3D (Mesh is already one)
  return mesh;
}
